    String name();
    default String greet() {
        return "hi " + name();
    }
}
Greeter g = () -> "Ana";
System.out.println(g.greet());
What does this program print?

A helper picks the higher-ranked of two objects and neither the helper nor the variables name the class behind them:
interface Ranked {
    int rank();
}
class Task implements Ranked {
    private final String name;
    private final int rank;
    Task(String name, int rank) {
        this.name = name;
        this.rank = rank;
    }
    public int rank() {
        return rank;
    }
    public String toString() {
        return name + ":" + rank;
    }
}
static Ranked best(Ranked a, Ranked b) {
    return a.rank() >= b.rank() ? a : b;
}
Ranked t1 = new Task("write", 3);
Ranked t2 = new Task("test", 8);
System.out.println(best(t1, t2));
What does this program print?
